/* Little Learners service worker (generated by tools/build_sw.py; edit tools/sw.template.js). */
const VERSION = "__VERSION__";
const CACHE_PREFIX = "little-learners-";
const CACHE = CACHE_PREFIX + VERSION;

// Paths are relative to this file, so the site works at / or under /repo-name/.
const PRECACHE = __PRECACHE__;

// Safari refuses to use a redirected response for a navigation, so store a clean copy.
async function clean(res) {
  if (!res.redirected) return res;
  const body = await res.blob();
  return new Response(body, { status: res.status, statusText: res.statusText, headers: res.headers });
}

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await Promise.all(PRECACHE.map(async (url) => {
      const res = await fetch(new Request(url, { cache: "reload" }));
      if (!res.ok) throw new Error("Precache failed for " + url + ": " + res.status);
      await cache.put(url, await clean(res));
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith(CACHE_PREFIX) && k !== CACHE).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

// Cache-first: everything is precached; anything new is fetched and kept.
self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    if (req.mode === "navigate") {
      if (url.pathname.endsWith("/")) {
        const idx = await cache.match(url.pathname + "index.html");
        if (idx) return idx;
      } else if (await cache.match(url.pathname + "/")) {
        // "/colors" -> "/colors/" (like the web server does), so relative links keep working offline
        return Response.redirect(url.pathname + "/" + url.search, 301);
      }
    }
    try {
      const res = await fetch(req);
      if (res.ok && res.type === "basic") cache.put(req, (await clean(res.clone())));
      return res;
    } catch (err) {
      if (req.mode === "navigate") {
        const home = await cache.match(new URL("./", self.location).pathname);
        if (home) return home;
      }
      throw err;
    }
  })());
});
